na me bhaktaḥ praṇaśyati\"}}]}]]]}]\n"])self.__next_f.push([1,"2d:[\"$\",\"div\",\"2787-synonyms,2787-synonyms\",{\"className\":\"av-synonyms\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Synonyms\"}],[[\"$\",\"$L2a\",\"child-2790\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:2:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base text-justify\",\"children\":[[\"$\",\"span\",\"wfwundefined-0\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-kṣipram\",{\"href\":\"/en/search/synonyms/?original=kṣipram\",\"children\":[\"$\",\"em\",null,{\"children\":\"kṣipram\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"very soon\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-1\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-bhavati\",{\"href\":\"/en/search/synonyms/?original=bhavati\",\"children\":[\"$\",\"em\",null,{\"children\":\"bhavati\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"becomes\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-2\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-dharma\",{\"href\":\"/en/search/synonyms/?original=dharma\",\"children\":[\"$\",\"em\",null,{\"children\":\"dharma\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-ātmā\",{\"href\":\"/en/search/synonyms/?original=ātmā\",\"children\":[\"$\",\"em\",null,{\"children\":\"ātmā\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"righteous\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-3\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-śaśvat\",{\"href\":\"/en/search/synonyms/?original=śaśvat\",\"children\":[\"$\",\"em\",null,{\"children\":\"śaśvat\"}]}],\"-\",[\"$\",\"$L20\",\"wfwu